import requests
from unittest.mock import patch

def test_bytes_method_conversion():
    captured = {}
    def fake_send(self, prep, **kwargs):
        captured['method'] = prep.method
        # Return a minimal response to avoid further processing
        class Resp:
            status_code = 200
            headers = {}
            content = b''
            history = []
            url = prep.url
            reason = 'OK'
        return Resp()
    with patch('requests.sessions.Session.send', fake_send):
        sess = requests.Session()
        sess.request(b'GET', 'http://example.com', allow_redirects=False)
    # The bug: method becomes literal string "b'GET'" (after .upper() -> "B'GET'")
    assert captured['method'] == 'GET', f"Expected method 'GET', got {captured['method']!r}"

